<?php
$ubah = ($row !== NULL);
$v = function ($k, $def = '') use ($row, $old) {
	if (!empty($old) && array_key_exists($k, $old)) return (string) $old[$k];
	if ($row && array_key_exists($k, $row) && $row[$k] !== NULL) return (string) $row[$k];
	return $def;
};
?>
