acing:.14em;text-transform:uppercase}.field textarea{width:100%;min-height:130px;resize:vertical;padding:12px 14px;border:1px solid var(--line);color:var(--text);font:400 14px var(--body)}.check{display:flex!important;align-items:center;gap:10px;text-transform:none!important;letter-spacing:0!important;color:var(--text)!important}.hint{margin:7px 0 0;color:var(--muted);font-size:11px}.current{margin-top:10px;padding:12px;background:var(--soft)}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}@media(max-width:800px){.top{padding:0 18px}.user{display:none}.layout{display:block}.sidebar{width:auto;padding:8px;display:flex;flex-direction:row;overflow:auto}.sidebar a{white-space:nowrap;border-left:0;border-bottom:3px solid transparent}.sidebar .logout{margin-top:0}.wrap{padding:30px 20px}h1{font-size:32px}.grid{padding:22px}}
